var { FileBlob, SpreadsheetFile } = await import('@oai/artifact-tool');
var fs = await import('node:fs/promises');
var files = [
  '/Users/lyston/Downloads/文章池导出_2026-05-25.xlsx',
  '/Users/lyston/Downloads/文章池导出_2026-05-25 (1).xlsx'
];
var summaries = [];
for (const path of files) {
  const input = await FileBlob.load(path);
  const wb = await SpreadsheetFile.importXlsx(input);
  const sheetNames = wb.worksheets.items.map(s => s.name);
  const perSheet = [];
  for (const sheetName of sheetNames) {
    const inspected = await wb.inspect({ kind: 'table', range: `${sheetName}!A1:Z25`, include: 'values,formulas', tableMaxRows: 25, tableMaxCols: 26 });
    perSheet.push({ sheetName, ndjson: inspected.ndjson });
  }
  summaries.push({ path, sheetNames, perSheet });
}
nodeRepl.write(JSON.stringify(summaries, null, 2));

